def restore_acceleration(name, source):
    if name in ('sequential_cycle.py', 'sequential_worker.py'):
        source = source.replace('from bounded_release_alignment import ', 'from release_alignment import ')
    from speed_source import restore_speed_source
    source = restore_speed_source(name, source)
    if name == 'execute_cycle.py' and CURRENT_LEG_METHOD in source:
        if source.count(CURRENT_LEG_METHOD) != 1:
            raise ValueError('Ambiguous stationary leg method delta')
        source = source.replace(CURRENT_LEG_METHOD, ORIGINAL_LEG_METHOD, 1)
    if name == 'execute_cycle.py' and CURRENT_LEG_CHECK in source:
        if source.count(CURRENT_LEG_CHECK) != 1:
            raise ValueError('Ambiguous initialization seam')
        source = source.replace(CURRENT_LEG_CHECK, ORIGINAL_LEG_ACTIVATION, 1)
    if name == 'sequential_worker.py' and CURRENT_PICKUP_DECLARATION in source:
        if source.count(CURRENT_PICKUP_DECLARATION) != 1:
            raise ValueError('Ambiguous planning seam')
        source = source.replace(CURRENT_PICKUP_DECLARATION, ORIGINAL_PICKUP_PREDICTION, 1)
    if name in ('inputs/robot_dual.urdf', 'robot_dual.urdf'):
        for side in ('left', 'right'):
            current = CURRENT_SOLES[side]
            original = f'''<collision>
      <origin rpy="0 0 0" xyz="0 0 0" />
      <geometry>
        <mesh filename="package://h1_2_description/meshes/{side}_ankle_roll_link.STL" />
      </geometry>
    </collision>'''
            source = source.replace(current, original, 1)
        source = source.removesuffix('\n')
    return source


def restore_acceleration_bytes(name, content):
    if name == 'sequential_cycle.py':
        return restore_acceleration(name, content.decode()).encode()
    if name not in ('execute_cycle.py', 'execute_loading.py', 'execute_sequential.py', 'execute_coherent.py', 'execute_dual.py', 'trace_io.py', 'sequential_worker.py', 'inputs/robot_dual.urdf', 'robot_dual.urdf'):
        return content
    return restore_acceleration(name, content.decode()).encode()
